// Database query execution function
const timestamp = new Date().toISOString();
const requestBody = msg.payload;

// Validate request
if (!requestBody.query) {
    msg.payload = {
        error: 'Missing query parameter',
        timestamp: timestamp
    };
    msg.statusCode = 400;
    return msg;
}

const query = requestBody.query;
const database = requestBody.database || 'main_db';

// Simulate query execution based on database and query type
let result;

if (query.toLowerCase().includes('select count')) {
    result = {
        rows: [{ count: Math.floor(Math.random() * 10000) }],
        rowCount: 1,
        executionTime: Math.floor(Math.random() * 50) + 'ms'
    };
} else if (query.toLowerCase().includes('select')) {
    // Simulate SELECT query results
    const sampleData = generateSampleData(query);
    result = {
        rows: sampleData,
        rowCount: sampleData.length,
        executionTime: Math.floor(Math.random() * 100) + 'ms'
    };
} else if (query.toLowerCase().includes('insert') || 
           query.toLowerCase().includes('update') || 
           query.toLowerCase().includes('delete')) {
    // Simulate DML operations
    result = {
        affectedRows: Math.floor(Math.random() * 10) + 1,
        executionTime: Math.floor(Math.random() * 200) + 'ms'
    };
} else {
    result = {
        message: 'Query executed successfully',
        executionTime: Math.floor(Math.random() * 30) + 'ms'
    };
}

// Generate response
const response = {
    timestamp: timestamp,
    database: database,
    query: query,
    status: 'success',
    result: result
};

msg.payload = response;
msg.statusCode = 200;
return msg;

function generateSampleData(query) {
    if (query.toLowerCase().includes('horse')) {
        return [
            { horse_name: 'Thunder Bay', jockey: 'J. Smith', odds: 3.5 },
            { horse_name: 'Swift Arrow', jockey: 'M. Johnson', odds: 7.2 },
            { horse_name: 'Gold Rush', jockey: 'S. Williams', odds: 2.8 }
        ];
    } else if (query.toLowerCase().includes('race')) {
        return [
            { race_id: 1, race_time: '14:30', track: 'Ascot' },
            { race_id: 2, race_time: '15:00', track: 'Newmarket' },
            { race_id: 3, race_time: '15:30', track: 'Cheltenham' }
        ];
    } else {
        return [
            { id: 1, name: 'Sample Data 1', value: 100 },
            { id: 2, name: 'Sample Data 2', value: 200 }
        ];
    }
}

